import os,re,itertools
fs=[f for f in os.listdir('.') if f!='_book.md']
def toks(f):
    t=open(f,encoding='utf-8').read().lower()
    m=t.find('**what it is**')
    return set(re.findall(r'[a-z]{5,}',t[m:m+1500]))
T={f:toks(f) for f in fs}
res=[]
